'use strict';
(()=>{
 const is=r=>r.category==='公积金'||/公积金/.test(r.source||'');window.FamilyProvident={is};
 const panel=document.createElement('article');panel.className='panel provident-panel';panel.id='providentPanel';panel.innerHTML='<div class="panel-head"><div><h2>公积金 · 单独录入与定期入账</h2><p>计入期间家庭收入和账户余额，曲线与普通收入分开展示。请选择实际公积金到账的人民币账户。</p></div></div><form id="fundManualForm" class="form-grid"><label class="field">收入归属<select id="fundMember" required></select></label><label class="field">到账账户<select id="fundAccount" required></select></label><label class="field">到账日期<input id="fundDate" type="date" required></label><label class="field">本次公积金金额（人民币）<input id="fundAmount" type="number" min="0.01" step="0.01" required></label><label class="field full">备注<input id="fundMemo" maxlength="120"></label><button type="submit" class="solid">保存公积金收入</button></form><details id="fundRecurring"><summary>设置每月自动录入</summary><p class="muted">为上方所选成员设置。新计划从本月或以后开始；当月已到入账日时，保存后立即补录。当月已有公积金时不再自动重复录入。暂停不删除已入账记录。</p><form id="fundRuleForm" class="form-grid"><label class="field">每月公积金（人民币）<input id="fundRuleAmount" type="number" min="0.01" step="0.01" required></label><label class="field">每月入账日<input id="fundRuleDay" type="number" min="1" max="31" required value="1"></label><label class="field">起始月份<input id="fundRuleStart" type="month" required></label><label class="income-confirm"><input id="fundRuleEnabled" type="checkbox" checked>启用自动录入</label><button type="submit" class="solid">保存定期设置</button></form><p class="muted">使用上方选择的成员和到账账户。日期超过该月天数时取月末；NAS运行期间自动执行，停机后的未入账月份会在恢复运行时检查补录。已关账或账户异常时提示处理。</p></details><p id="fundStatus" role="status"></p><div id="fundRules"></div>';$('monthPane-flows').append(panel);
 let initialized=false,rules=[],requestId=FamilyClient.newId(),loading=false;
 function accounts(){const member=$('fundMember').value,old=$('fundAccount').value;$('fundAccount').replaceChildren(new Option('请选择到账账户',''));for(const a of (D.accounts||[]).filter(a=>!a.archivedAt&&a.currency==='CNY'&&[member,'共同'].includes(a.owner)))$('fundAccount').append(new Option(memberName(a.owner)+' · '+a.name,a.id));if([...$('fundAccount').options].some(o=>o.value===old))$('fundAccount').value=old;}
 function rule(){const r=rules.find(r=>r.member===$('fundMember').value);$('fundRuleAmount').value=r?.amount||'';$('fundRuleDay').value=r?.day||1;$('fundRuleStart').value=r?.startMonth||D.today.slice(0,7);$('fundRuleEnabled').checked=r?.enabled??true;if(r&&[...$('fundAccount').options].some(o=>o.value===r.account))$('fundAccount').value=r.account;}
 async function load(){if(!D.live||loading)return;loading=true;try{const response=await api('/api/provident');rules=response.rules;const old=$('fundMember').value,me=window.currentFamilyUser;const profiles=(D.memberProfiles||[]).filter(p=>p.active&&(!me||me.role==='admin'||p.key===me.member));$('fundMember').replaceChildren(...profiles.map(p=>new Option(p.name,p.key)));$('fundMember').value=profiles.some(p=>p.key===old)?old:profiles.some(p=>p.key===me?.member)?me.member:profiles[0]?.key||'';accounts();if(!initialized){$('fundDate').value=D.today;initialized=true;}if(!document.activeElement?.closest('#fundRuleForm,#fundManualForm'))rule();$('fundDate').max=D.today;$('fundRules').replaceChildren();for(const r of rules){const p=document.createElement('p');p.className='muted';p.textContent=memberName(r.member)+' · 每月 '+money(Math.round(Number(r.amount)*100))+' · '+r.day+'日 · '+r.startMonth+'起 · '+(r.enabled?'已启用':'已暂停');if(r.enabled&&(!me||me.role==='admin'||me.member===r.member)){const b=document.createElement('button');b.type='button';b.className='outline';b.textContent='暂停';b.onclick=async()=>{b.disabled=true;try{await api('/api/provident/rule',{...r,enabled:false});await refreshLedger();await load();$('fundStatus').textContent='已暂停，已入账记录保留。';}catch(e){$('fundStatus').textContent=e.message;}finally{b.disabled=false;}};p.append(' ',b);}$('fundRules').append(p);}for(const e of response.errors||[]){const p=document.createElement('p');p.className='import-warning';p.textContent=memberName(e.member)+' '+(e.month||'')+'：'+e.error;$('fundRules').append(p);}}catch(e){$('fundStatus').textContent=e.message;}finally{loading=false;}}
 $('fundMember').onchange=()=>{accounts();rule();requestId=FamilyClient.newId();};for(const id of ['fundAccount','fundDate','fundAmount','fundMemo'])$(id).addEventListener('input',()=>requestId=FamilyClient.newId());
 $('fundManualForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await api('/api/provident/manual',{requestId,member:$('fundMember').value,account:$('fundAccount').value,date:$('fundDate').value,amount:$('fundAmount').value,memo:$('fundMemo').value});await refreshLedger();$('fundAmount').value='';requestId=FamilyClient.newId();$('fundStatus').textContent=r.alreadyImported?'已保存过，没有重复入账。':'公积金已保存，家庭收入和账户余额已更新；公积金曲线单独统计。';}catch(x){$('fundStatus').textContent=x.message;}finally{button.disabled=false;}};
 $('fundRuleForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await api('/api/provident/rule',{member:$('fundMember').value,account:$('fundAccount').value,amount:$('fundRuleAmount').value,day:Number($('fundRuleDay').value),startMonth:$('fundRuleStart').value,enabled:$('fundRuleEnabled').checked});await refreshLedger();await load();$('fundStatus').textContent='定期设置已保存。'+(r.count?'本次已自动录入 '+r.count+' 条。':'')+(r.errors?.length?'部分月份需要处理，请看下方提示。':'');}catch(x){$('fundStatus').textContent=x.message;}finally{b.disabled=false;}};
 document.addEventListener('family-ledger-ready',load);document.addEventListener('family-session-ready',load);window.addEventListener('hashchange',()=>{if(location.hash==='#entry')load();});if(D.live)load();
})();
